const items = $input.all().map(item => item.json || {});
const market = items.find(item => item.USD || item['gram-altin'] || item.gumus) || {};
const btc = items.find(item => item.bitcoin?.usd || item.price || item.symbol) || {};

function parseTr(value) {
  if (typeof value === 'number') return value;
  const cleaned = String(value ?? '')
    .replace(/\$/g, '')
    .replace(/\s/g, '')
    .replace(/\./g, '')
    .replace(',', '.');
  const number = Number(cleaned);
  return Number.isFinite(number) && number > 0 ? number : null;
}

function mid(row) {
  if (!row) return null;
  const buy = parseTr(row['Alış'] ?? row.Buying ?? row.buying);
  const sell = parseTr(row['Satış'] ?? row.Selling ?? row.selling);
  if (buy && sell) return (buy + sell) / 2;
  return sell || buy || null;
}

const usdTry = mid(market.USD);
const gramGoldTry = mid(market['gram-altin'] || market.GRA);
const gramSilverTry = mid(market.gumus || market.GUMUS);
const btcUsd = parseTr(btc.bitcoin?.usd ?? btc.price ?? btc.lastPrice);

if (!usdTry || !gramGoldTry || !gramSilverTry || !btcUsd) {
  throw new Error('Piyasa verisi eksik: USDTRY=' + usdTry + ', gramAltin=' + gramGoldTry + ', gramGumus=' + gramSilverTry + ', BTC=' + btcUsd);
}

function fmtTry(value, digits = 2) {
  return Number(value).toLocaleString('tr-TR', { minimumFractionDigits: digits, maximumFractionDigits: digits });
}
function fmtUsd(value, digits = 0) {
  return Number(value).toLocaleString('en-US', { minimumFractionDigits: digits, maximumFractionDigits: digits });
}

const content = 'Piyasalarda sabah görünümü\n\n'
  + 'Gram altın: ' + fmtTry(gramGoldTry) + ' TL\n'
  + 'Dolar/TL: ' + fmtTry(usdTry, 4) + '\n'
  + 'Gram gümüş: ' + fmtTry(gramSilverTry) + ' TL\n'
  + 'Bitcoin: ' + fmtUsd(btcUsd) + ' $';

return [{
  json: {
    content,
    hash: 'market-' + new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Istanbul' }),
    title: 'Piyasalarda sabah görünümü',
    trendScore: '',
    imageUrl: '',
    pubDate: new Date().toISOString(),
    link: 'market-prices'
  }
}];

const items = $input.all().map(item => item.json || {});
const staticData = $getWorkflowStaticData('global');
staticData.youtubePublishedIds = Array.isArray(staticData.youtubePublishedIds) ? staticData.youtubePublishedIds : [];

const postedLinks = new Set();
const postedHashes = new Set();
const postedVideoIds = new Set(staticData.youtubePublishedIds.map(String));
if (staticData.lastYouTubeVideoId) postedVideoIds.add(String(staticData.lastYouTubeVideoId));

function decode(value) {
  return String(value || '')
    .replace(/\\u([0-9a-fA-F]{4})/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
    .replace(/\\u0026/g, '&')
    .replace(/\\u003d/g, '=')
    .replace(/\\u002F/g, '/')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#34;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/\\"/g, '"')
    .trim();
}

function normalize(value) {
  return decode(value)
    .toLocaleLowerCase('tr-TR')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\u0131/g, 'i');
}

function videoIdFrom(value) {
  const text = decode(value);
  const patterns = [
    /(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/live\/|youtube\.com\/embed\/)([A-Za-z0-9_-]{11})/i,
    /(?:videoId|video_id|yt:video)[:"=\s]+([A-Za-z0-9_-]{11})/i,
    /^([A-Za-z0-9_-]{11})$/
  ];
  for (const regex of patterns) {
    const match = text.match(regex);
    if (match) return match[1];
  }
  return '';
}

function normalizeYoutubeLink(value) {
  const id = videoIdFrom(value);
  return id ? 'https://www.youtube.com/watch?v=' + id : decode(value).trim();
}

for (const item of items) {
  if (item.Link || item.Hash || item.Baslik || item['Tweet Metni']) {
    const link = String(item.Link || item.link || '').trim();
    const hash = String(item.Hash || item.hash || '').trim();
    const tweet = String(item['Tweet Metni'] || item.content || '').trim();
    if (link) {
      const normalized = normalizeYoutubeLink(link);
      postedLinks.add(normalized);
      const id = videoIdFrom(normalized);
      if (id) postedVideoIds.add(id);
    }
    if (hash) {
      postedHashes.add(hash);
      const hashId = hash.replace(/^youtube-/, '');
      if (/^[A-Za-z0-9_-]{11}$/.test(hashId)) postedVideoIds.add(hashId);
    }
    const tweetId = videoIdFrom(tweet);
    if (tweetId) postedVideoIds.add(tweetId);
  }
}

function htmlFrom(item) {
  const strings = [];
  for (const value of Object.values(item || {})) {
    if (typeof value === 'string' && value.length > 100) strings.push(value);
  }
  return strings.join('\n');
}

function looksBadYoutubeTitle(title, context = '') {
  const t = normalize(title);
  const c = normalize(context);
  if (!t || t.length < 8) return true;
  const badPhrases = [
    'bu kanala abone olmak istiyor musunuz',
    'kanala abone olmak istiyor musunuz',
    'abone olmak istiyor musunuz',
    'abone ol',
    'subscribe to this channel',
    'want to subscribe',
    'oturum ac',
    'giris yap',
    'bildirimleri ac',
    'bildirim al',
    'paylas',
    'share',
    'kaydet',
    'save',
    'daha sonra izle',
    'watch later',
    'siraya ekle',
    'add to queue',
    'tumunu oynat',
    'play all'
  ];
  if (badPhrases.some(phrase => t.includes(phrase))) return true;
  if (t.includes('abone') && c.includes('subscribebutton')) return true;
  return false;
}

function looksShort(title, context = '') {
  const text = normalize(title + ' ' + context);
  return /#shorts|\bshorts\b|\/shorts\/|shortslockupviewmodel|reelwatchendpoint|\bkisa video\b/.test(text);
}

function looksLive(title, context = '', pageKind = '') {
  const text = normalize(title + ' ' + context);
  if (pageKind === 'stream') return true;
  return /canli|live now|live broadcast|yayinda|yayini|upcomingeventdata|islivenow|premiere|prömiyer/.test(text);
}

function parseTime(value) {
  const t = Date.parse(value || '');
  return Number.isFinite(t) ? t : 0;
}

function extractVideosFromHtml(html, pageKind) {
  const out = [];
  const seen = new Set();
  const text = String(html || '');
  const patterns = [
    /"videoId":"([A-Za-z0-9_-]{11})"[\s\S]{0,3600}?"title":\{"runs":\[\{"text":"([^"]+)"/g,
    /"videoId":"([A-Za-z0-9_-]{11})"[\s\S]{0,3600}?"title":\{"simpleText":"([^"]+)"/g,
    /"url":"\/watch\?v=([A-Za-z0-9_-]{11})"[\s\S]{0,3600}?"title":\{"runs":\[\{"text":"([^"]+)"/g
  ];
  for (const regex of patterns) {
    let match;
    while ((match = regex.exec(text)) !== null) {
      const videoId = match[1];
      const title = decode(match[2]);
      const context = text.slice(Math.max(0, match.index - 1400), Math.min(text.length, match.index + 5200));
      if (!videoId || !title || seen.has(videoId)) continue;
      if (looksBadYoutubeTitle(title, context)) continue;
      if (looksShort(title, context)) continue;
      seen.add(videoId);
      out.push({
        videoId,
        title,
        link: 'https://www.youtube.com/watch?v=' + videoId,
        kind: looksLive(title, context, pageKind) ? 'stream' : 'video',
        source: 'youtube-page-' + pageKind,
        pubTime: 0
      });
      if (out.length >= 20) break;
    }
  }
  return out;
}

function extractVideoFromRss(item) {
  const title = decode(item.title || item.name || '');
  const desc = decode(item.contentSnippet || item.description || item.content || '');
  const rawLink = item.link || item.guid || item.id || item.url || '';
  const packed = JSON.stringify(item).slice(0, 2000);
  const videoId = videoIdFrom(rawLink) || videoIdFrom(item.id) || videoIdFrom(item.guid) || videoIdFrom(packed);
  if (!videoId || !title) return null;
  if (looksBadYoutubeTitle(title, desc)) return null;
  if (looksShort(title, desc + ' ' + rawLink)) return null;
  return {
    videoId,
    title,
    link: 'https://www.youtube.com/watch?v=' + videoId,
    kind: looksLive(title, desc, '') ? 'stream' : 'video',
    source: 'youtube-rss',
    pubTime: parseTime(item.isoDate || item.pubDate || item.published || item.updated || item.date)
  };
}

let videos = [];
const htmlItems = items.map(htmlFrom).filter(Boolean);
for (let i = 0; i < htmlItems.length; i++) {
  const pageKind = i === 1 ? 'stream' : 'video';
  videos.push(...extractVideosFromHtml(htmlItems[i], pageKind));
}

for (const item of items) {
  const probe = String(item.link || item.guid || item.id || item.url || '') + ' ' + JSON.stringify(item).slice(0, 800);
  const isYoutubeItem = /youtube\.com\/watch|youtu\.be\/|yt:video|youtube\.com\/feeds/i.test(probe);
  if (!isYoutubeItem) continue;
  const video = extractVideoFromRss(item);
  if (video) videos.push(video);
}

const byId = new Map();
for (const item of videos) {
  if (!byId.has(item.videoId)) byId.set(item.videoId, item);
  else {
    const old = byId.get(item.videoId);
    if ((item.pubTime || 0) > (old.pubTime || 0) || item.source === 'youtube-rss') byId.set(item.videoId, item);
  }
}

const all = [...byId.values()];
if (!all.length) return [];

all.sort((a, b) => {
  const timeDelta = (b.pubTime || 0) - (a.pubTime || 0);
  if (timeDelta) return timeDelta;
  const rssDelta = Number(b.source === 'youtube-rss') - Number(a.source === 'youtube-rss');
  if (rssDelta) return rssDelta;
  return Number(b.kind === 'stream') - Number(a.kind === 'stream');
});

// Important: only the latest channel item may be posted. If latest is already posted, do not backfill older videos.
const post = all[0];
const normalizedLink = normalizeYoutubeLink(post.link);
const alreadyPosted = postedVideoIds.has(post.videoId) || postedLinks.has(normalizedLink) || postedHashes.has('youtube-' + post.videoId);
if (alreadyPosted) return [];

staticData.lastYouTubeVideoId = post.videoId;
staticData.youtubePublishedIds = [post.videoId, ...staticData.youtubePublishedIds.filter(id => id !== post.videoId)].slice(0, 80);
staticData.lastYouTubeLink = normalizedLink;
staticData.lastYouTubePublishedAt = new Date().toISOString();

const liveLike = post.kind === 'stream';
const prefix = liveLike ? 'Kanal canlı yayında:' : 'Kanal yeni video yayında:';

return [{
  json: {
    title: post.title,
    link: normalizedLink,
    content: prefix + '\n\n' + post.title + '\n\n' + normalizedLink,
    hash: 'youtube-' + post.videoId,
    category: liveLike ? 'YouTube Canli' : 'YouTube Video',
    imageUrl: 'https://i.ytimg.com/vi/' + post.videoId + '/hqdefault.jpg',
    source: post.source,
    pubDate: post.pubTime ? new Date(post.pubTime).toISOString() : new Date().toISOString(),
    duplicateCheck: 'latest-only-static-and-sheet'
  }
}];

const allItems = $input.all();

const TREND_FRESH_HOURS = 0;
const MAX_NEWS_AGE_HOURS = 24;
const MAX_SHEET_ROWS_TO_SCAN = 350;
const NIGHT_START_HOUR = 3;
const NIGHT_END_HOUR = 7;
const NIGHT_MAX_NON_CRITICAL_POSTS = 2;
const IN_FLIGHT_LOCK_TTL_HOURS = 12;
const LOCK_NAMESPACE = 'newsPublishLocksV2';
const EXECUTION_MODE = typeof $execution !== 'undefined' ? String($execution.mode || '') : '';
const IS_MANUAL_TEST = EXECUTION_MODE === 'manual' || EXECUTION_MODE === 'test';

const STOP_WORDS = new Set([
  'icin','ile','olan','oldu','sonra','once','gibi','daha','cok','az','bir','iki','yeni','son','dakika','haber','haberi','aciklama','acikladi','geldi','gelen','karsi','uzere','baskan','bakan','turkiye','turk','de','da','ve','veya','ama','fakat','mi','mu','ne','bu','su','o','en','ilk','sonu','sonuc','sonuclari','canli','video','foto','fotograf','goruntu','gundem','ekonomi','teknoloji','spor','the','and','for','with','from','that','this','into','about','after','before','over','under','says','said','new','news','live','latest','breaking','update','updates','video','photos','business','politics','world','report','reports','market','markets','will','are','has','have','was','were','their','its','who','what','when','where','why','how','google','trend','trends'
]);

const AD_PATTERNS = [
  /reklam|sponsor|sponsorlu|advertorial|tanitim|tanıtım|ilan|kampanya|indirim|firsat|fırsat|kupon|cekilis|çekiliş|hediye|alisveris|alışveriş/i,
  /pirlanta|pırlanta|tek\s*tas|tek\s*taş|alyans|mucevher|mücevher|jewellery|jewelry|yuzuk|yüzük/i,
  /satilik|satılık|emlak|konut projesi|otomobil kampanyasi|otomobil kampanyası/i,
  /marka is birligi|marka iş birliği|is birligiyle|iş birliğiyle/i
];

function stripHtml(value) {
  return String(value || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<br\s*\/?>(\s*)/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeText(value) {
  return stripHtml(value)
    .toLocaleLowerCase('tr-TR')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\u0131/g, 'i')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function canonicalUrl(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  try {
    const url = new URL(raw);
    url.hash = '';
    for (const key of [...url.searchParams.keys()]) {
      if (/^(utm_|fbclid|gclid|yclid|mc_)/i.test(key)) url.searchParams.delete(key);
    }
    return url.toString().replace(/\/$/, '');
  } catch (error) {
    return raw.replace(/\s+/g, '').replace(/\/$/, '');
  }
}

function sourceDomain(link) {
  try { return new URL(link).hostname.replace(/^www\./, ''); }
  catch { return ''; }
}

function sourceLabelFor(domain) {
  const labels = {
    'ntv.com.tr': 'NTV',
    'sozcu.com.tr': 'Sozcu',
    'ekonomim.net': 'Ekonomim',
    'dunyatimes.com': 'Dunya Times',
    'onedio.com': 'Onedio',
    'nytimes.com': 'The New York Times',
    'washingtonpost.com': 'The Washington Post',
    'mynet.com': 'Mynet',
    'milliyet.com.tr': 'Milliyet',
    'bbc.co.uk': 'BBC',
    'dw.com': 'DW Turkce',
    'rss.dw.com': 'DW Turkce',
    'theguardian.com': 'The Guardian',
    'aljazeera.com': 'Al Jazeera'
  };
  return labels[domain] || domain || '';
}

function hashText(value) {
  const text = String(value || '');
  let hash = 2166136261;
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    hash += (hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

function decodeMaybe(value) {
  let text = String(value || '').replace(/&amp;/g, '&').trim();
  if (/%2F|%3A|%3F|%26/i.test(text)) {
    try { text = decodeURIComponent(text); } catch {}
  }
  return text;
}

function normalizeImageUrl(value, baseUrl = '') {
  let url = decodeMaybe(value);
  if (!url) return '';
  if (url.startsWith('//')) url = 'https:' + url;
  try { url = new URL(url, baseUrl || undefined).toString(); } catch {}
  return url;
}

function collectImageCandidates(value, keyPath = '', out = []) {
  if (value === null || value === undefined) return out;
  const keyText = String(keyPath || '').toLowerCase();

  if (typeof value === 'string') {
    const raw = value;
    const urls = raw.match(/https?:\/\/[^\s"'<>\\)]+/gi) || [];
    for (const url of urls) out.push({ url, keyPath });

    const htmlAttrs = [...raw.matchAll(/(?:src|href|content|url)=['"]([^'"]+)['"]/gi)];
    for (const match of htmlAttrs) out.push({ url: match[1], keyPath: keyPath + '.html' });

    if (/^https?:\/\//i.test(raw.trim())) out.push({ url: raw.trim(), keyPath });
    return out;
  }

  if (Array.isArray(value)) {
    value.forEach((entry, index) => collectImageCandidates(entry, keyPath + '[' + index + ']', out));
    return out;
  }

  if (typeof value === 'object') {
    const typeHint = normalizeText(value.type || value.medium || value.mime || value.mimeType || value.contentType || '');
    const objectHint = /image|img|thumb|thumbnail|media|enclosure|photo|resim|gorsel|görsel/.test(keyText) || /image|jpeg|jpg|png|webp/.test(typeHint);

    for (const [key, entry] of Object.entries(value)) {
      const nextPath = keyPath ? keyPath + '.' + key : key;
      if (objectHint && typeof entry === 'string' && /^(https?:)?\/\//i.test(entry.trim())) out.push({ url: entry, keyPath: nextPath + '.hinted' });
      collectImageCandidates(entry, nextPath, out);
    }
  }

  return out;
}

function imageScore(url, keyPath = '') {
  const value = normalizeImageUrl(url);
  if (!/^https?:\/\//i.test(value)) return -999;
  if (/(logo|favicon|sprite|avatar|profile|tracking|pixel|doubleclick|google-analytics|1x1|blank|spacer|transparent|adsystem|adservice|banner|svg|placeholder|default-image|google-news|news-google)/i.test(value)) return -999;
  if (/news\.google\.|googleusercontent\.com|gstatic\.com|google\.com\/images|google\.com\/logos|lh3\.googleusercontent\.com/i.test(value)) return -999;

  let score = 0;
  if (/\.(jpe?g|png|webp)(\?|$)/i.test(value)) score += 90;
  if (/(image|images|img|photo|photos|thumb|thumbnail|media|cdn|resim|gorsel|görsel|haberresim|upload|uploads|i\.ytimg|pbs\.twimg)/i.test(value)) score += 50;
  if (/(image|img|thumb|thumbnail|media|enclosure|photo|resim|gorsel|görsel|urltoimage)/i.test(keyPath)) score += 45;
  if (/(width|w)=([6-9]\d{2}|[1-9]\d{3,})/i.test(value)) score += 8;
  if (/(height|h)=([3-9]\d{2}|[1-9]\d{3,})/i.test(value)) score += 6;
  if (/\/\d{3,}x\d{3,}\//.test(value)) score += 8;
  return score;
}

function getImageUrl(json) {
  const candidates = collectImageCandidates(json)
    .map(item => ({ url: normalizeImageUrl(item.url, json.link || json.guid || ''), keyPath: item.keyPath }))
    .filter(item => item.url);

  const unique = [];
  const seen = new Set();
  for (const item of candidates) {
    const key = item.url.split('#')[0];
    if (seen.has(key)) continue;
    seen.add(key);
    unique.push(item);
  }

  unique.sort((a, b) => imageScore(b.url, b.keyPath) - imageScore(a.url, a.keyPath));
  const best = unique.find(item => imageScore(item.url, item.keyPath) >= 80);
  return best?.url || '';
}

function imageKeyFor(value) {
  const raw = normalizeImageUrl(value);
  if (!/^https?:\/\//i.test(raw)) return '';
  try {
    const url = new URL(raw);
    url.hash = '';
    url.search = '';
    return (url.hostname.replace(/^www\./, '') + url.pathname).toLocaleLowerCase('tr-TR').replace(/\/$/, '');
  } catch {
    return raw.split('?')[0].split('#')[0].toLocaleLowerCase('tr-TR').replace(/\/$/, '');
  }
}

function parseDate(value) {
  const time = value ? Date.parse(value) : NaN;
  return Number.isFinite(time) ? time : 0;
}

function tokensFor(value) {
  return normalizeText(value)
    .split(/\s+/)
    .filter(word => word.length > 3 && !STOP_WORDS.has(word) && !/^\d+$/.test(word));
}

function eventKeyFor(json) {
  const title = normalizeText(json.title || json.Baslik || '');
  const desc = normalizeText(json.description || json.contentSnippet || json.content || '').slice(0, 300);
  const tokens = [...new Set((title + ' ' + desc).split(/\s+/).filter(word => word.length > 3 && !STOP_WORDS.has(word) && !/^\d+$/.test(word)))];
  return tokens.sort().slice(0, 9).join(' ');
}

function fingerprintFor(json) {
  const text = [json.title, json.Baslik, json.description, json.contentSnippet, json.content, json['Tweet Metni'], json.Kategori, json.category, json.link, json.Link].filter(Boolean).join(' ');
  const tokens = [...new Set(tokensFor(text))];
  const important = tokens.filter(token => token.length >= 5 || /\d{4}/.test(token));
  return { text: normalizeText(text), tokens: new Set(tokens), important: new Set(important) };
}

function overlapCount(a, b) {
  let count = 0;
  for (const token of a) if (b.has(token)) count++;
  return count;
}

function isSimilar(a, b) {
  if (!a.tokens.size || !b.tokens.size) return false;
  const overlap = overlapCount(a.tokens, b.tokens);
  const minSize = Math.min(a.tokens.size, b.tokens.size);
  const unionSize = new Set([...a.tokens, ...b.tokens]).size || 1;
  const importantOverlap = overlapCount(a.important, b.important);
  if (overlap >= 7 && overlap / minSize >= 0.60) return true;
  if (overlap >= 8 && overlap / unionSize >= 0.40) return true;
  if (importantOverlap >= 4 && overlap >= 6) return true;
  return false;
}

function isAdLike(json) {
  const text = [json.title, json.description, json.contentSnippet, json.content, json.link, json.category, json.categories?.join(' ')].filter(Boolean).join(' ');
  const normalized = normalizeText(text);
  return AD_PATTERNS.some(pattern => pattern.test(text) || pattern.test(normalized));
}

function hasRealEarthquakeDetails(json) {
  const title = normalizeText(json.title || json.Baslik || '');
  const text = normalizeText([json.title, json.description, json.contentSnippet, json.content, json.category, json.link].filter(Boolean).join(' '));
  if (!/deprem/.test(text)) return false;

  const titleIsGeneric = /(deprem mi oldu|deprem oldu mu|son depremler|guncel deprem listesi|deprem listesi|gunun son depremleri|en son deprem nerede|son deprem nerede)/.test(title);
  if (titleIsGeneric) return false;

  const magnitudePattern = /\b[1-9](?:[.,]\d)?\s*(buyuklugunde|siddetinde|ml|mw)\b|\bm\s*[=:]?\s*[1-9](?:[.,]\d)?\b/;
  const concreteEventPattern = /(merkez ussu|merkezussu|ilinde|ilcesinde|aciklarinda|meydana geldi|can kaybi|yarali|hasar|yikildi|artci|sarsildi|afad duyurdu|kandilli duyurdu)/;

  return magnitudePattern.test(title) || (magnitudePattern.test(text) && concreteEventPattern.test(text));
}

function isGenericEarthquakeTracker(json) {
  const text = normalizeText([json.title, json.description, json.contentSnippet, json.content, json.category, json.link].filter(Boolean).join(' '));
  if (!/deprem/.test(text)) return false;

  const genericTrackerPattern = /(son depremler|guncel deprem listesi|deprem listesi|deprem mi oldu|deprem oldu mu|kandilli rasathanesi|afad ve kandilli|afad kandilli|gunun son depremleri|deprem verileri|son depremleri takip|sarsintilar izlenebiliyor|resmi kaynaklardan sorgulanabiliyor|son deprem nerede|en son deprem nerede|deprem sorgulama)/;
  if (!genericTrackerPattern.test(text)) return false;

  return !hasRealEarthquakeDetails(json);
}

function isCriticalNews(json) {
  const text = normalizeText([json.title, json.description, json.contentSnippet, json.content, json.category, json.link].filter(Boolean).join(' '));
  if (/(deprem|tsunami|patlama|saldiri|saldırı|yangin|yangın|sel|firtina|fırtına|heyelan|afet|ucak dustu|uçak düştü|helikopter|tren kazasi|tren kazası|maden kazasi|maden kazası|sehit|şehit|suikast|rehine|savas|savaş|catism|çatışm|bombali|bombalı|teror|terör)/.test(text)) return true;
  if (/(cumhurbaskani|bakan|meclis|mahkeme|savci|savcı|gozalti|gözaltı|tutuklama|istifa|yasak)/.test(text) && /(son dakika|acil|kritik|flash|flas|sicak|sıcak)/.test(text)) return true;
  return false;
}

function isVeryCriticalNews(json) {
  const text = normalizeText([json.title, json.description, json.contentSnippet, json.content, json.category, json.link].filter(Boolean).join(' '));
  if (/(deprem|tsunami|patlama|bombali|bombalı|saldiri|saldırı|teror|terör|silahli saldiri|silahlı saldırı|yangin|yangın|sel|firtina|fırtına|heyelan|afet|ucak dustu|uçak düştü|helikopter dustu|helikopter düştü|tren kazasi|tren kazası|maden kazasi|maden kazası|sehit|şehit|suikast|rehine|savas|savaş|catism|çatışm|kimyasal|nukleer|nükleer)/.test(text)) return true;
  if (/(son dakika|acil|kritik|flash|flas|sicak|sıcak)/.test(text) && /(can kaybi|can kaybı|olu|ölü|yarali|yaralı|tahliye|alarm|patlama|deprem|saldiri|saldırı|afet)/.test(text)) return true;
  return false;
}

function localParts(dateValue) {
  const date = dateValue ? new Date(dateValue) : new Date();
  if (Number.isNaN(date.getTime())) return null;
  const parts = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Istanbul', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }).formatToParts(date).reduce((acc, part) => {
    if (part.type !== 'literal') acc[part.type] = part.value;
    return acc;
  }, {});
  const hour = Number(parts.hour === '24' ? '0' : parts.hour);
  return { dateKey: parts.year + '-' + parts.month + '-' + parts.day, hour };
}

function isNightNow() {
  const parts = localParts(new Date());
  return parts && parts.hour >= NIGHT_START_HOUR && parts.hour < NIGHT_END_HOUR;
}

function isBlockedPublishSource(json) {
  const link = canonicalUrl(json.link || json.guid || json.url || '');
  const domain = sourceDomain(link);
  const title = normalizeText(json.title || '');
  return domain.includes('news.google.') || domain.includes('trends.google.') || domain === 'google.com' || domain.endsWith('.google.com') || title.includes('google news') || title.includes('google haber');
}

function isGoogleTrendItem(json) {
  const link = canonicalUrl(json.link || json.guid || json.url || '');
  const domain = sourceDomain(link);
  const keys = Object.keys(json || {}).join(' ').toLocaleLowerCase('tr-TR');
  return domain.includes('trends.google') || domain.includes('news.google.com') || keys.includes('approx') || keys.includes('traffic') || normalizeText(json.link || '').includes('trends google');
}

function lockKeysForCandidate(item) {
  const keys = [];
  const canonical = canonicalUrl(item.canonicalUrl || item.link || item.guid || '');
  const eventKey = item.eventKey || eventKeyFor(item);
  const imageKey = item.imageKey || imageKeyFor(item.imageUrl || getImageUrl(item));
  const tokenKey = [...new Set(tokensFor([item.title, item.description, item.contentSnippet, item.content].filter(Boolean).join(' ')))]
    .sort()
    .slice(0, 12)
    .join(' ');

  if (canonical) keys.push('url:' + hashText(canonical));
  if (item.hash) keys.push('hash:' + String(item.hash));
  if (eventKey) keys.push('event:' + hashText(eventKey));
  if (imageKey) keys.push('img:' + hashText(imageKey));
  if (tokenKey) keys.push('tok:' + hashText(tokenKey));

  return [...new Set(keys)];
}

function getLockStore() {
  try {
    if (typeof $getWorkflowStaticData !== 'function') return null;
    const data = $getWorkflowStaticData('global');
    if (!data[LOCK_NAMESPACE] || typeof data[LOCK_NAMESPACE] !== 'object') data[LOCK_NAMESPACE] = {};
    return data[LOCK_NAMESPACE];
  } catch {
    return null;
  }
}

function cleanupLockStore(store, nowMs) {
  if (!store) return;
  const ttlMs = IN_FLIGHT_LOCK_TTL_HOURS * 36e5;
  for (const [key, value] of Object.entries(store)) {
    const time = Number(value) || 0;
    if (!time || nowMs - time > ttlMs) delete store[key];
  }
}

function isCandidateLocked(item, store, nowMs) {
  if (!store) return false;
  const ttlMs = IN_FLIGHT_LOCK_TTL_HOURS * 36e5;
  return lockKeysForCandidate(item).some(key => store[key] && nowMs - Number(store[key]) <= ttlMs);
}

function lockCandidate(item, store, nowMs) {
  const keys = lockKeysForCandidate(item);
  if (!store) return keys;
  for (const key of keys) store[key] = nowMs;
  return keys;
}

const sheetRowsRaw = [];
const rssRows = [];
const trendRows = []; // Google Trends iptal: bos kalir, skora etki etmez.

for (const item of allItems) {
  const json = item.json || {};
  if (json.Link || json.Hash || json.Baslik || json['Tweet Metni']) {
    sheetRowsRaw.push(json);
    continue;
  }
  if (json.title && (json.link || json.guid || json.pubDate || json.isoDate)) {
    if (isGoogleTrendItem(json)) continue;
    rssRows.push(json);
  }
}

const sheetRows = sheetRowsRaw.slice(-MAX_SHEET_ROWS_TO_SCAN);
const postedLinks = new Set();
const postedHashes = new Set();
const postedKeys = new Set();
const postedFingerprints = [];
const postedImageKeys = new Set();
const now = Date.now();
const nowLocal = localParts(new Date());
let nightNormalPostCount = 0;

for (const row of sheetRows) {
  const link = canonicalUrl(row.Link || row.link || row.URL || row.url || '');
  if (link) postedLinks.add(link);
  const hash = String(row.Hash || row.hash || '').trim();
  if (hash) postedHashes.add(hash);
  const key = eventKeyFor({ title: row.Baslik || row.title || '', description: row['Tweet Metni'] || row.description || '' });
  if (key) postedKeys.add(key);
  const fingerprint = fingerprintFor(row);
  if (fingerprint.tokens.size) postedFingerprints.push(fingerprint);
  const postedImageKey = imageKeyFor(row['Gorsel URL'] || row.imageUrl || row.Image || row.image || '');
  if (postedImageKey) postedImageKeys.add(postedImageKey);

  const category = normalizeText(row.Kategori || row.category || '');
  const rowDate = row['Yayinlanma Tarihi'] || row.pubDate || row.date || row.created || '';
  const rowLocal = rowDate ? localParts(rowDate) : null;
  if (nowLocal && rowLocal && rowLocal.dateKey === nowLocal.dateKey && rowLocal.hour >= NIGHT_START_HOUR && rowLocal.hour < NIGHT_END_HOUR && !/(youtube|market|piyasa)/.test(category)) nightNormalPostCount++;
}

let newestTrendTime = 0;
const trendTokenSet = new Set();
const trendTitles = [];
const trendsFresh = false;

const candidates = [];
for (const json of rssRows) {
  if (isBlockedPublishSource(json)) continue;
  if (isAdLike(json)) continue;
  if (isGenericEarthquakeTracker(json)) continue;

  const rawLink = json.link || json.guid || json.url || '';
  const canonical = canonicalUrl(rawLink);
  const eventKey = eventKeyFor(json) || normalizeText(json.title || '').slice(0, 90) || canonical;
  const hash = hashText(eventKey || canonical);
  const fingerprint = fingerprintFor(json);
  const looksPosted = postedFingerprints.some(posted => isSimilar(fingerprint, posted));

  if (!canonical || postedLinks.has(canonical) || postedHashes.has(hash) || postedHashes.has(eventKey) || postedKeys.has(eventKey) || looksPosted) continue;

  const imageUrl = getImageUrl(json);
  const imageKey = imageKeyFor(imageUrl);
  const imageAlreadyPosted = imageKey && postedImageKeys.has(imageKey);
  if (imageAlreadyPosted) continue;
  const source = sourceDomain(canonical);
  const pubTime = parseDate(json.isoDate || json.pubDate || json.date || json.published || json.created);
  const ageHours = pubTime ? Math.max(0, (now - pubTime) / 36e5) : 24;
  if (pubTime && ageHours > MAX_NEWS_AGE_HOURS) continue;

  const isCritical = isCriticalNews(json);
  const isVeryCritical = isVeryCriticalNews(json);
  const matchedTerms = [...fingerprint.tokens].filter(token => trendTokenSet.has(token));
  const trendOverlap = matchedTerms.length;

  candidates.push({
    ...json,
    link: rawLink,
    canonicalUrl: canonical,
    eventKey,
    hash,
    imageUrl,
    imageKey,
    hasImage: Boolean(imageUrl),
    source,
    sourceLabel: sourceLabelFor(source),
    pubTime,
    ageHours,
    isCritical,
    isVeryCritical,
    trendOverlap,
    trendMatchedTerms: matchedTerms.slice(0, 8).join(', '),
    dedupeTokens: [...fingerprint.tokens],
    cleanTitle: stripHtml(json.title || ''),
    cleanDescription: stripHtml(json.description || json.contentSnippet || json.content || ''),
  });
}

const lockStore = getLockStore();
cleanupLockStore(lockStore, now);
const availableCandidates = lockStore ? candidates.filter(item => !isCandidateLocked(item, lockStore, now)) : candidates;
const lockedCandidateCount = candidates.length - availableCandidates.length;

if (!availableCandidates.length) return [];

const imageCandidateCount = availableCandidates.filter(item => item.hasImage).length;
let eligible = imageCandidateCount > 0 ? availableCandidates.filter(item => item.hasImage) : availableCandidates;

if (!IS_MANUAL_TEST && isNightNow()) {
  eligible = eligible.filter(item => item.isVeryCritical);
  if (!eligible.length) return [];
}

const groups = [];
for (const item of eligible) {
  const tokens = new Set(item.dedupeTokens || String(item.eventKey || '').split(/\s+/).filter(Boolean));
  let target = null;
  for (const group of groups) {
    const overlap = [...tokens].filter(token => group.tokens.has(token)).length;
    const smallerSize = Math.min(tokens.size || 1, group.tokens.size || 1);
    const neededOverlap = Math.min(4, Math.max(2, Math.ceil(smallerSize * 0.52)));
    if (overlap >= neededOverlap) { target = group; break; }
  }
  if (!target) {
    target = { key: item.eventKey || item.hash, tokens, items: [] };
    groups.push(target);
  } else {
    for (const token of tokens) target.tokens.add(token);
  }
  target.items.push(item);
}

const grouped = [];
for (const group of groups) {
  const groupItems = group.items;
  groupItems.sort((a, b) => {
    const timeDelta = (b.pubTime || 0) - (a.pubTime || 0);
    if (timeDelta) return timeDelta;
    const imageDelta = Number(Boolean(b.imageUrl)) - Number(Boolean(a.imageUrl));
    if (imageDelta) return imageDelta;
    return Number(Boolean(b.isCritical)) - Number(Boolean(a.isCritical));
  });
  const best = groupItems[0];
  const sources = [...new Set(groupItems.map(item => item.source).filter(Boolean))];
  grouped.push({ best, sources, count: groupItems.length, key: group.key });
}

grouped.sort((a, b) => {
  const timeDelta = (b.best.pubTime || 0) - (a.best.pubTime || 0);
  if (timeDelta) return timeDelta;
  const imageDelta = Number(Boolean(b.best.imageUrl)) - Number(Boolean(a.best.imageUrl));
  if (imageDelta) return imageDelta;
  return Number(Boolean(b.best.isCritical)) - Number(Boolean(a.best.isCritical));
});

const winner = grouped[0];
const best = winner.best;
const selectionMode = best.imageUrl ? 'image-rss-priority' : 'text-only-no-image-in-rss-pool';
const displayScore = Math.max(0, 200 - Math.round((best.ageHours || 0) * 20)) + (best.isCritical ? 30 : 0) + Math.min(20, (best.trendOverlap || 0) * 5) + (best.imageUrl ? 100 : 0);
const reservedLockKeys = lockCandidate(best, lockStore, now);

return [{
  json: {
    ...best,
    title: best.cleanTitle || best.title,
    description: best.cleanDescription || best.description || '',
    link: best.link,
    canonicalUrl: best.canonicalUrl,
    imageUrl: best.imageUrl,
    source: best.source,
    sourceLabel: best.sourceLabel,
    category: best.isVeryCritical ? 'RSS Cok Kritik' : (best.isCritical ? 'RSS Kritik' : 'RSS Haber'),
    eventKey: winner.key,
    hash: best.hash,
    trendScore: Math.round(displayScore),
    matchedSources: winner.sources.join(', '),
    matchedCount: winner.count,
    selectionMode,
    imageCandidateCount,
    totalCandidateCount: candidates.length,
    lockedCandidateCount,
    reservedLockKeys: reservedLockKeys.join(', '),
    trendsFresh,
    trendSample: '',
