function decode(value) {
  return String(value || '')
    .replace(/\\u0026/g, '&')
    .replace(/\\u003d/g, '=')
    .replace(/\\u002F/g, '/')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#34;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/\\"/g, '"')
    .trim();
}

function htmlFrom(value) {
  if (!value) return '';
  if (typeof value === 'string') return value;
  const strings = [];
  const seen = new Set();
  function walk(v, depth = 0) {
    if (depth > 4 || v == null) return;
    if (typeof v === 'string') {
      const s = v.trim();
      if (s.length > 120 && !seen.has(s)) {
        seen.add(s);
        strings.push(s);
      }
      return;
    }
    if (Array.isArray(v)) return v.slice(0, 20).forEach(x => walk(x, depth + 1));
    if (typeof v === 'object') Object.values(v).slice(0, 60).forEach(x => walk(x, depth + 1));
  }
  walk(value);
  strings.sort((a, b) => {
    const as = /og:image|twitter:image|<html|<meta/i.test(a) ? 1 : 0;
    const bs = /og:image|twitter:image|<html|<meta/i.test(b) ? 1 : 0;
    return bs - as || b.length - a.length;
  });
  return strings[0] || '';
}

function absoluteUrl(url, base) {
  const raw = decode(url);
  if (!raw) return '';
  if (/^https?:\/\//i.test(raw)) return raw;
  if (raw.startsWith('//')) return 'https:' + raw;
  try { return new URL(raw, base || original.canonicalUrl || original.link || undefined).toString(); }
  catch { return ''; }
}

function sourceDomainFromUrl(value) {
  try { return new URL(String(value || '')).hostname.toLowerCase().replace(/^www\./, ''); }
  catch { return ''; }
}

function isBlockedGoogleNewsLink(value) {
  const domain = sourceDomainFromUrl(value);
  return domain.includes('news.google.') || domain.includes('trends.google.') || domain === 'google.com' || domain.endsWith('.google.com');
}

function looksBadImage(url) {
  const lower = String(url || '').toLowerCase();
  if (!/^https?:\/\//.test(lower)) return true;
  if (/favicon|logo|sprite|avatar|profile|pixel|tracking|doubleclick|googletag|analytics|placeholder|default-image|google-news|news-google|\.svg(?:\?|$)/.test(lower)) return true;
  if (/news\.google\.|googleusercontent\.com|gstatic\.com|google\.com\/images|google\.com\/logos|lh3\.googleusercontent\.com/.test(lower)) return true;
  return false;
}

function scoreImage(url) {
  const lower = String(url || '').toLowerCase();
  let score = 0;
  if (/\.(jpe?g|png|webp|avif)(\?|#|$)/.test(lower)) score += 70;
  if (/og:image|twitter:image/.test(lower)) score += 10;
  if (/i\.guim\.co\.uk|media\.guim\.co\.uk|static\.guim\.co\.uk|image|images|media|photo|cdn|upload/.test(lower)) score += 35;
  if (/(width|w)=([6-9]\d{2}|[1-9]\d{3,})/i.test(url)) score += 8;
  if (/(height|h)=([3-9]\d{2}|[1-9]\d{3,})/i.test(url)) score += 6;
  if (/\/\d{3,}x\d{3,}\//.test(url)) score += 8;
  if (looksBadImage(url)) score -= 100;
  return score;
}

function collectMetaImages(html) {
  const text = String(html || '');
  const found = [];
  const patterns = [
    /<meta\b[^>]*(?:property|name)=["'](?:og:image(?::secure_url)?|twitter:image(?::src)?)["'][^>]*content=["']([^"']+)["'][^>]*>/gi,
    /<meta\b[^>]*content=["']([^"']+)["'][^>]*(?:property|name)=["'](?:og:image(?::secure_url)?|twitter:image(?::src)?)["'][^>]*>/gi,
    /<link\b[^>]*rel=["']image_src["'][^>]*href=["']([^"']+)["'][^>]*>/gi,
    /<link\b[^>]*href=["']([^"']+)["'][^>]*rel=["']image_src["'][^>]*>/gi,
    /"image"\s*:\s*"(https?:\\?\/\\?\/[^"\\]+)"/gi,
    /"url"\s*:\s*"(https?:\\?\/\\?\/[^"\\]+\.(?:jpg|jpeg|png|webp|avif)(?:\?[^"\\]*)?)"/gi
  ];
  for (const regex of patterns) {
    let match;
    while ((match = regex.exec(text)) !== null) {
      const url = decode(match[1]).replace(/\\\//g, '/');
      if (url) found.push(url);
      if (found.length > 30) break;
    }
  }
  return found;
}

const html = htmlFrom(input);
const base = original.canonicalUrl || original.link || '';
if (isBlockedGoogleNewsLink(base)) {
  return [{ json: { ...original, imageUrl: '', hasImage: false, imageSource: 'blocked-google-news-link', imageDebug: { blocked: true, reason: 'Google News link is radar-only, not publish media.' } } }];
}
const rawRssImage = absoluteUrl(original.imageUrl || '', base);
const rssImage = rawRssImage && !looksBadImage(rawRssImage) ? rawRssImage : '';
const articleImages = collectMetaImages(html)
  .map(url => absoluteUrl(url, base))
  .filter(url => url && !looksBadImage(url));
const unique = [...new Set([rssImage, ...articleImages].filter(Boolean))];
unique.sort((a, b) => scoreImage(b) - scoreImage(a));
const imageUrl = unique[0] || '';

return [{ json: {
